WITH "g1" AS (SELECT DATE_TRUNC('MONTH', CONVERT_TIMEZONE('UTC', 'Asia/Ho_Chi_Minh', "t0"."order_date")) AS "order_date_month", COUNT(CASE WHEN "t0"."order_date" >= TIMESTAMP '2025-12-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-09-30 17:00:00' THEN 1 END) AS "orders" FROM "sales"."orders" AS "t0" WHERE ("t0"."status" = 'DONE') AND ("t0"."order_date" >= TIMESTAMP '2025-12-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-09-30 17:00:00') GROUP BY DATE_TRUNC('MONTH', CONVERT_TIMEZONE('UTC', 'Asia/Ho_Chi_Minh', "t0"."order_date"))) SELECT "g1"."order_date_month" AS "order_date_month", "g1"."orders" AS "orders", SUM("g1"."orders") OVER (ORDER BY "g1"."order_date_month" ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS "orders_to_date", ("g1"."orders" - LAG("g1"."orders") OVER (ORDER BY "g1"."order_date_month")) * 1.0 / NULLIF(LAG("g1"."orders") OVER (ORDER BY "g1"."order_date_month"), 0) * 100 AS "mom_pct", AVG("g1"."orders") OVER (ORDER BY "g1"."order_date_month" ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS "avg_3_months" FROM "g1" ORDER BY "order_date_month" ASC LIMIT 1000
